/// Untrusted URL claim supplied by the retail client during secure
/// registration.  The retail client may omit `address` and `port` because the
/// server discovers the authoritative endpoint from the authenticated socket.
/// Keeping the raw wire value prevents this compatibility exception from
/// becoming a normal StationURL or inventing an endpoint during serialization.
#[derive(Debug, Clone)]
pub struct UntrustedRegistrationUrl {
    raw: String,
}

impl UntrustedRegistrationUrl {
    pub fn parse(raw: String) -> Result<Self, quazal::rmc::types::StationURLParseError> {
        let Some((scheme, rest)) = raw.split_once(":/") else {
            return Err(quazal::rmc::types::StationURLParseError::MissingScheme);
        };
        if scheme.is_empty() {
            return Err(quazal::rmc::types::StationURLParseError::MissingScheme);
        }

        for parameter in rest.split(';') {
            let Some((key, value)) = parameter.split_once('=') else {
                return Err(quazal::rmc::types::StationURLParseError::InvalidParameters);
            };
            match key {
                "address" if value.is_empty() => {
                    return Err(quazal::rmc::types::StationURLParseError::MissingAddress);
                }
                "port" => {
                    let _: u16 = value.parse()?;
                }
                _ => {}
            }
        }
        Ok(Self { raw })
    }

    pub fn as_str(&self) -> &str {
        &self.raw
    }
}

impl quazal::rmc::basic::FromStream for UntrustedRegistrationUrl {
    fn from_stream<R>(stream: &mut quazal::rmc::basic::ReadStream<R>) -> Result<Self, quazal::rmc::basic::FromStreamError>
    where
        R: byteorder::ReadBytesExt,
    {
        Self::parse(stream.read::<String>()?).map_err(Into::into)
    }
}

impl quazal::rmc::basic::ToStream for UntrustedRegistrationUrl {
    fn to_stream<W>(&self, stream: &mut quazal::rmc::basic::WriteStream<W>) -> std::io::Result<usize>
    where
        W: byteorder::WriteBytesExt,
    {
        stream.write(&self.raw)
    }
}

#[derive(Debug, ToStream, FromStream)]
pub struct ConnectionData {
    pub station_url: quazal::rmc::types::StationURL,
    pub connection_id: u32,
}

#[cfg(test)]
mod tests {
    use quazal::rmc::basic::FromStream;
    use quazal::rmc::basic::ToStream;

    use super::*;

    #[test]
    fn untrusted_registration_url_preserves_the_missing_address_wire_value() {
        let raw = "prudps:/port=3074;sid=15;type=3".to_string();
        let encoded = raw.to_bytes();
        let registration = UntrustedRegistrationUrl::from_bytes(&encoded).unwrap();
        assert_eq!(registration.as_str(), raw);
        assert_eq!(registration.to_bytes(), encoded);

        assert!(matches!(
            raw.parse::<quazal::rmc::types::StationURL>(),
            Err(quazal::rmc::types::StationURLParseError::MissingAddress)
        ));
    }

    #[test]
    fn untrusted_registration_url_preserves_the_missing_endpoint_wire_value() {
        let raw = "prudps:/sid=15;type=3".to_string();
        let encoded = raw.to_bytes();
        let registration = UntrustedRegistrationUrl::from_bytes(&encoded).unwrap();
        assert_eq!(registration.as_str(), raw);
        assert_eq!(registration.to_bytes(), encoded);
    }

    #[test]
    fn untrusted_registration_url_rejects_empty_address_or_invalid_port() {
        assert!(matches!(
            UntrustedRegistrationUrl::parse("prudps:/address=;port=3074".to_string()),
            Err(quazal::rmc::types::StationURLParseError::MissingAddress)
        ));
        assert!(matches!(
            UntrustedRegistrationUrl::parse("prudps:/port=invalid;sid=15".to_string()),
            Err(quazal::rmc::types::StationURLParseError::InvalidPort(_))
        ));
    }
}
